CREATE OR REPLACE FUNCTION public.fn_mint_social_alias(p_seed text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_w1 text[];
  v_w2 text[];
  v_base text;
  v_cand text;
  v_n integer := 0;
  v_h bigint;
BEGIN
  SELECT array_agg(w ORDER BY w) INTO v_w1
    FROM (SELECT DISTINCT (regexp_match(alias, '^([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;
  SELECT array_agg(w ORDER BY w) INTO v_w2
    FROM (SELECT DISTINCT (regexp_match(alias, '^[A-Z][a-z]+([A-Z][a-z]+)'))[1] AS w
            FROM public.content_authors) s
   WHERE w IS NOT NULL;

  IF v_w1 IS NULL OR v_w2 IS NULL
     OR COALESCE(array_length(v_w1, 1), 0) = 0
     OR COALESCE(array_length(v_w2, 1), 0) = 0 THEN
    RAISE EXCEPTION 'fn_mint_social_alias: no alias vocabulary to draw from';
  END IF;

  v_h := abs(hashtext(p_seed));

  LOOP
    v_base := v_w1[1 + ((v_h + v_n * 7919) % array_length(v_w1, 1))]
           || v_w2[1 + (((v_h / 17) + v_n * 104729) % array_length(v_w2, 1))];
    -- Pure handles first. Once fifty probes have all collided we are in a
    -- crowded corner of the space, so take the discriminator rather than
    -- probing forever: this is the safety net that 2026-09-01 did not have.
    v_cand := CASE WHEN v_n < 50 THEN v_base ELSE v_base || (v_n - 49)::text END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.content_authors WHERE alias = v_cand);
    v_n := v_n + 1;
    IF v_n > 100000 THEN
      RAISE EXCEPTION 'fn_mint_social_alias: could not mint a free alias for %', p_seed;
    END IF;
  END LOOP;

  RETURN v_cand;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_socialize_horse(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  p record; ca record; v_h bigint; v_loc text; v_tz text; v_spec text; v_stakes text; v_alias text; v_voice text; v_arch text; v_cad int; v_bday date; v_touched boolean := false;
  v_locs text[] := ARRAY['Atlantic City, NJ','Austin, TX','Barcelona, ES','Berlin, DE','Brooklyn, NY','Chicago, IL','Dallas, TX','Denver, CO','Dublin, IE','Las Vegas, NV','Lisbon, PT','London, UK','Los Angeles, CA','Manchester, UK','Manila, PH','Melbourne, AU','Miami, FL','Phoenix, AZ','Seattle, WA','Toronto, CA'];
  v_tzs text[] := ARRAY['America/New_York','America/Chicago','Europe/Madrid','Europe/Berlin','America/New_York','America/Chicago','America/Chicago','America/Denver','Europe/Dublin','America/Los_Angeles','Europe/Lisbon','Europe/London','America/Los_Angeles','Europe/London','Asia/Manila','Australia/Melbourne','America/New_York','America/Phoenix','America/Los_Angeles','America/Toronto'];
  v_specs text[] := ARRAY['bounty tournaments','cash games','heads-up','live cash','mixed games','PLO','satellites','short deck','spins','tournaments'];
  v_stk text[] := ARRAY['1/2','1/3','10/25','2/3','2/5','25/50','5/10'];
  v_voices text[] := ARRAY['analytical','blunt','hype','dry','veteran','casual','skeptical','excitable','terse','conversational','community','technical','storyteller','grinder','coach'];
  v_archs text[] := ARRAY['blunt','analytical','hype','dry','veteran','casual','skeptical','excitable','terse','conversational'];
BEGIN
  SELECT * INTO p FROM public.profiles WHERE id = p_id;
  IF NOT FOUND OR NOT COALESCE(p.is_horse, false) THEN RETURN false; END IF;
  v_h := abs(hashtext(p_id::text));
  v_loc := v_locs[1 + (v_h % 20)]; v_tz := v_tzs[1 + (v_h % 20)]; v_spec := v_specs[1 + ((v_h / 7) % 10)]; v_stakes := v_stk[1 + ((v_h / 11) % 7)];
  v_voice := v_voices[1 + ((v_h / 13) % array_length(v_voices, 1))]; v_arch := v_archs[1 + ((v_h / 17) % array_length(v_archs, 1))];
  v_cad := public.fn_fleet_cadence(p_id);
  v_bday := date '1972-01-01' + ((v_h / 23) % (365 * 30))::int;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  IF NOT FOUND THEN
    v_alias := public.fn_mint_social_alias(p_id::text);
    INSERT INTO public.content_authors (name, alias, location, timezone, specialty, stakes, bio, avatar_seed, avatar_url, profile_id, is_active, voice, birthday, personality)
    VALUES (COALESCE(NULLIF(p.display_name, ''), NULLIF(p.full_name, ''), p.username), v_alias, v_loc, v_tz, v_spec, v_stakes, v_spec || ' regular out of ' || v_loc || '. Mostly ' || v_stakes || '.', lower(v_alias) || '_' || substr(md5(p_id::text), 1, 8), p.avatar_url, p_id, true, v_voice, v_bday, jsonb_build_object('archetype', v_arch, 'cadence_per_week', v_cad, 'seeded_by', 'fn_socialize_horse', 'seeded_at', now()));
    v_touched := true;
    SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  END IF;
  UPDATE public.content_authors SET is_active = true,
      location = COALESCE(NULLIF(location, ''), v_loc), timezone = COALESCE(NULLIF(timezone, ''), v_tz), specialty = COALESCE(NULLIF(specialty, ''), v_spec), stakes = COALESCE(NULLIF(stakes, ''), v_stakes),
      bio = COALESCE(NULLIF(bio, ''), v_spec || ' regular out of ' || COALESCE(NULLIF(location,''), v_loc) || '. Mostly ' || COALESCE(NULLIF(stakes,''), v_stakes) || '.'),
      voice = COALESCE(NULLIF(voice, ''), v_voice), birthday = COALESCE(birthday, v_bday), avatar_url = COALESCE(avatar_url, p.avatar_url),
      personality = COALESCE(personality, '{}'::jsonb)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'archetype' THEN '{}'::jsonb ELSE jsonb_build_object('archetype', v_arch) END
                    || jsonb_build_object('cadence_per_week', v_cad)
                    || CASE WHEN COALESCE(personality, '{}'::jsonb) ? 'seeded_by' THEN '{}'::jsonb ELSE jsonb_build_object('seeded_by', 'fn_socialize_horse', 'seeded_at', now()) END
  WHERE profile_id = p_id
    AND (NOT is_active OR COALESCE(location,'') = '' OR COALESCE(timezone,'') = '' OR COALESCE(specialty,'') = '' OR COALESCE(stakes,'') = '' OR COALESCE(bio,'') = '' OR COALESCE(voice,'') = '' OR birthday IS NULL OR avatar_url IS NULL OR personality IS NULL OR NOT (personality ? 'archetype') OR (personality->>'cadence_per_week') IS DISTINCT FROM v_cad::text);
  IF FOUND THEN v_touched := true; END IF;
  SELECT * INTO ca FROM public.content_authors WHERE profile_id = p_id;
  UPDATE public.profiles SET bio = COALESCE(NULLIF(bio, ''), ca.bio), city = COALESCE(NULLIF(city, ''), split_part(ca.location, ',', 1)), favorite_game = COALESCE(NULLIF(favorite_game, ''), ca.specialty), birth_year = COALESCE(birth_year, EXTRACT(YEAR FROM ca.birthday)::int), social_profile_completed = true, updated_at = now()
  WHERE id = p_id AND (COALESCE(bio,'') = '' OR COALESCE(city,'') = '' OR COALESCE(favorite_game,'') = '' OR birth_year IS NULL OR NOT COALESCE(social_profile_completed, false));
  IF FOUND THEN v_touched := true; END IF;
  RETURN v_touched;
END; $function$

CREATE OR REPLACE FUNCTION public.trg_fn_horse_is_born_social()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF COALESCE(NEW.is_horse, false) THEN
    BEGIN
      PERFORM public.fn_socialize_horse(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_socialize_horse(%) failed in trigger: % (the sweep will catch it)', NEW.id, SQLERRM;
    END;
  END IF;
  RETURN NULL;
END;
$function$
